import functools

def natural_sort_strings(strings):
    """Sort strings into natural order.

    Split each string into maximal ASCII-digit and non-digit runs.
    Compare digit runs by integer value; non-digit runs by case-sensitive
    Unicode lexical order. Text tokens sort before numeric tokens when kinds
    differ. Shorter equal-prefix token lists sort first; equal keys preserve
    input order. Empty strings are allowed; Unicode digits are treated as text.

    Args:
        strings: A list of strings to sort.

    Returns:
        A new list containing the strings sorted naturally.
    """
    def _tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if 48 <= ord(ch) <= 57:
                j = i
                while j < n and 48 <= ord(s[j]) <= 57:
                    j += 1
                tokens.append(('num', int(s[i:j])))
                i = j
            else:
                tokens.append(('str', s[i:j]))
                i = j
        return tokens

    def _key(s):
        tokens = _tokenize(s)
        key_parts = []
        for kind, val in tokens:
            if kind == 'num':
                key_parts.append((0, val))
            else:
                key_parts.append((1, val))
        return key_parts

    @functools.cmp_to_key
    def _compare(a, b):
        ka = _key(a)
        kb = _key(b)
        # Compare token by token
        min_len = min(len(ka), len(kb))
        for i in range(min_len):
            if ka[i] < kb[i]:
                return -1
            if ka[i] > kb[i]:
                return 1
        # Shorter key sorts first if one is a prefix of the other
        if len(ka) < len(kb):
            return -1
        if len(ka) > len(kb):
            return 1
        return 0

    return sorted(strings, key=functools.cmp_to_key(_compare))

